import generated from '../generated/docs-model.json';
import type { DocsModel, Page } from '../model/types';

/** Generated by `nx run osw/frp-gate:generate-model` from the README, the Go sources and `examples/` */
export const model = generated as DocsModel;

const pages = new Map(model.pages.map((page) => [page.slug, page]));

export const getPage = (slug: string): Page | undefined => pages.get(slug);

/** Image reference shown in the header and the pull command */
export const IMAGE_REF = `ghcr.io/${model.image}`;

/** The sidebar group a page belongs to, e.g. `Guide` */
export const groupOf = (slug: string) => model.nav.find((group) => group.slugs.includes(slug))?.title;

/** Pages in sidebar order, for previous / next links */
export const pageOrder: Page[] = model.nav.flatMap((group) => group.slugs.flatMap((slug) => pages.get(slug) ?? []));
